contract InvMutTest {
    C c;
    bool revertOnCall;

    constructor(C _c) { c = _c; }

    function run(address callee, bytes memory data) public {
        require(callee == address(this));
        // this contract's fallback reverts only when revertOnCall is true
        revertOnCall = false;
        bool revertedOk;
        try c.forward(callee, data) { revertedOk = false; }
        catch { revertedOk = true; }
        assert(!revertedOk); // successful call must not revert

        revertOnCall = true;
        bool revertedBad;
        try c.forward(callee, data) { revertedBad = false; }
        catch { revertedBad = true; }
        assert(revertedBad); // failing callee must make forward revert
    }

    fallback() external payable {
        require(!revertOnCall);
    }

    receive() external payable {}
}

