contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address callee) public {
        // Restrict the callee to this contract, whose receive and fallback always revert,
        // so the callee reverts on EVERY call regardless of calldata.
        require(callee == address(this));

        bool reverted;
        try c.forward(callee, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: forward must propagate the callee's revert.
        assert(reverted);
    }

    receive() external payable {
        revert();
    }

    fallback() external payable {
        revert();
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes calldata data) public {
        require(data.length < 1000);
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool reverted;
        try c.forward(address(this), data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: forwarding arbitrary calldata to a payable receiver
        // (this contract, whose receive and fallback always accept) succeeds
        // and moves no Ether: c's balance and the callee's balance are unchanged.
        assert(!reverted && address(c).balance == cBalBefore && address(this).balance == thisBalBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

