contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address strictCallee, bytes calldata data) public {
        uint balBefore = address(c).balance;
        bool reverted;
        if (data.length == 0) {
            (bool s,) = address(c).call(abi.encodeWithSelector(c.forward.selector, strictCallee, data));
            require(s);
            reverted = false;
        } else {
            (, bytes memory ret) = address(c).call(
                abi.encodeWithSelector(c.forward.selector, strictCallee, data)
            );
            reverted = _decodeRevert(ret);
        }
        assert((reverted == (data.length != 0)) && address(c).balance == balBefore);
    }

    function _decodeRevert(bytes memory ret) internal pure returns (bool) {
        return ret.length > 0 ? _revertFlag(ret) : true;
    }

    function _revertFlag(bytes memory ret) internal pure returns (bool) {
        if (ret.length == 4 && ret[0] == 0x08 && ret[1] == 0xc3 && ret[2] == 0x79 && ret[3] == 0xa0) {
            return false;
        }
        return true;
    }

    receive() external payable {}
}

